SELECT EXISTS (
    SELECT 1
    FROM conversation_participants
    WHERE conversation_id = #{conversationId}
      AND user_id = #{userId}
)

SELECT user_id
FROM conversation_participants
WHERE conversation_id = #{conversationId}

mapper.update:
UPDATE conversation_participants
SET last_read_message_id = #{lastReadMessageId}
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND last_read_message_id IS DISTINCT FROM #{lastReadMessageId}
  AND EXISTS (
    SELECT 1
    FROM messages new_msg
    WHERE new_msg.message_id = #{lastReadMessageId}
      AND new_msg.conversation_id = conversation_participants.conversation_id
  )
  AND (
    last_read_message_id IS NULL
    OR EXISTS (
        SELECT 1
        FROM messages new_msg
                 LEFT JOIN messages old_msg
                           ON old_msg.message_id = conversation_participants.last_read_message_id
        WHERE new_msg.message_id = #{lastReadMessageId}
          AND new_msg.conversation_id = conversation_participants.conversation_id
          AND (
            old_msg.message_id IS NULL
            OR new_msg.created_at > old_msg.created_at
            OR (
                new_msg.created_at = old_msg.created_at
                AND new_msg.message_id > old_msg.message_id
            )
          )
    )
  )

